class Solution {
static int gcdInt(int a,int b){while(b){int r=a%b;a=b;b=r;}return a;}
public:
    long long countPairs(vector<int>& nums, int k) {
        unordered_map<int,long long> cnt;long long ans=0;
        for(int x:nums) {
            int g=gcdInt(x,k);
            for(auto &p:cnt) if(1LL*g*p.first%k==0) ans+=p.second;
            ++cnt[g];
        }
        return ans;
    }
};
